import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"04 · 锁与死锁","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/db/04.md","filePath":"bagu/db/04.md"}'),o={name:"bagu/db/04.md"};function e(l,s,i,r,c,d){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_04-·-锁与死锁" tabindex="-1">04 · 锁与死锁 <a class="header-anchor" href="#_04-·-锁与死锁" aria-label="Permalink to &quot;04 · 锁与死锁&quot;">​</a></h1><blockquote><p>03 篇讲了&quot;不加锁&quot;的路（MVCC），这篇讲&quot;加锁&quot;的路。<strong>两条路配合，才是 InnoDB 的全貌。</strong></p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>锁的作用是<strong>让并发事务在修改同一份数据时排队</strong>。代价是并发度下降，所以<strong>锁的粒度越细越好，但要能管得住</strong>。</p><h2 id="生活类比-图书馆的借阅登记" tabindex="-1">生活类比：图书馆的借阅登记 <a class="header-anchor" href="#生活类比-图书馆的借阅登记" aria-label="Permalink to &quot;生活类比：图书馆的借阅登记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>锁</th><th>场景</th></tr></thead><tbody><tr><td>共享锁（S）</td><td>&quot;我在阅览室看这本书，你可以一起看，但谁都不能带走&quot;</td></tr><tr><td>排他锁（X）</td><td>&quot;我借走了，你们谁都别想&quot;</td></tr><tr><td>意向锁</td><td>门口挂个牌子：&quot;里面有人占了某个座位&quot;，让管理员不用挨个问</td></tr><tr><td>行锁</td><td>只锁这一本书</td></tr><tr><td>表锁</td><td>整个书架都锁了</td></tr><tr><td>间隙锁</td><td>锁住&quot;第 5 到第 10 本之间的空位&quot;，不让人往里插新书</td></tr><tr><td>死锁</td><td>A 拿着 1 号等 2 号，B 拿着 2 号等 1 号</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、锁的分类-两个维度" tabindex="-1">一、锁的分类（两个维度） <a class="header-anchor" href="#一、锁的分类-两个维度" aria-label="Permalink to &quot;一、锁的分类（两个维度）&quot;">​</a></h3><p><strong>维度 1：兼容性</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>共享锁（S 锁 / 读锁）：</span></span>
<span class="line"><span>  多个事务可以同时持有</span></span>
<span class="line"><span>  持有 S 锁时：别人能加 S，不能加 X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>排他锁（X 锁 / 写锁）：</span></span>
<span class="line"><span>  只能一个事务持有</span></span>
<span class="line"><span>  持有 X 锁时：别人既不能加 S，也不能加 X</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>S 锁</th><th>X 锁</th></tr></thead><tbody><tr><td><strong>S 锁</strong></td><td>✅ 兼容</td><td>❌ 冲突</td></tr><tr><td><strong>X 锁</strong></td><td>❌ 冲突</td><td>❌ 冲突</td></tr></tbody></table><p><strong>维度 2：粒度</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表级锁：</span></span>
<span class="line"><span>  - 表锁（LOCK TABLES）</span></span>
<span class="line"><span>  - 意向锁（IS / IX）：表示&quot;我打算给某行加 S/X 锁&quot;</span></span>
<span class="line"><span>  - 自增锁（AUTO-INC）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>行级锁：</span></span>
<span class="line"><span>  - 记录锁（Record Lock）：锁住某一条索引记录</span></span>
<span class="line"><span>  - 间隙锁（Gap Lock）：锁住记录之间的空隙</span></span>
<span class="line"><span>  - Next-Key Lock：记录锁 + 间隙锁，锁住左开右闭区间</span></span>
<span class="line"><span>  - 插入意向锁：插入前加，表示&quot;我要在这个间隙插入&quot;</span></span></code></pre></div><h3 id="二、意向锁-为什么需要它" tabindex="-1">二、意向锁：为什么需要它 <a class="header-anchor" href="#二、意向锁-为什么需要它" aria-label="Permalink to &quot;二、意向锁：为什么需要它&quot;">​</a></h3><p><strong>问题</strong>：事务 A 要给第 5 行加 X 锁。事务 B 要加表锁。B 怎么知道&quot;表里有没有行被锁&quot;？</p><p>如果没有意向锁，B 必须<strong>遍历所有行</strong>检查有没有行锁——太慢。</p><p><strong>解法</strong>：加行锁之前，先给表加一个&quot;意向锁&quot;。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务 A：LOCK 表（加 IX 意向锁）&gt; 再给第 5 行加 X 锁</span></span>
<span class="line"><span>事务 B：想加表锁 &gt; 看到表上有 IX &gt; 直接知道&quot;有人锁了行&quot; &gt; 等待</span></span></code></pre></div><p><strong>意向锁之间是兼容的</strong>（IS 和 IX 兼容），它只和表级的 S/X 锁冲突。</p><h3 id="三、innodb-的行锁是-加在索引上的" tabindex="-1">三、InnoDB 的行锁是&quot;加在索引上的&quot; <a class="header-anchor" href="#三、innodb-的行锁是-加在索引上的" aria-label="Permalink to &quot;三、InnoDB 的行锁是&quot;加在索引上的&quot;&quot;">​</a></h3><p><strong>这是最重要的一句话</strong>：<strong>InnoDB 的行锁锁的是索引记录，不是行本身</strong>。</p><p>推论：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 如果 WHERE 条件没走索引 &gt; 无法定位到索引记录 &gt; 只能锁全表（实际上是锁所有行）</span></span>
<span class="line"><span>② 如果走了索引 &gt; 只锁命中的索引记录</span></span></code></pre></div><p><strong>这就是&quot;没走索引的 UPDATE 会锁全表&quot;的原因</strong>，也是线上事故的高发点。</p><h3 id="四、三种行锁的区别" tabindex="-1">四、三种行锁的区别 <a class="header-anchor" href="#四、三种行锁的区别" aria-label="Permalink to &quot;四、三种行锁的区别&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设索引上有 id = 1, 5, 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【记录锁】锁住 id = 5 这一条</span></span>
<span class="line"><span>  SELECT * FROM t WHERE id = 5 FOR UPDATE;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【间隙锁】锁住 (1, 5) 这个空隙（不包含两端的记录）</span></span>
<span class="line"><span>  SELECT * FROM t WHERE id BETWEEN 2 AND 4 FOR UPDATE;</span></span>
<span class="line"><span>  &gt; 别人不能插入 id = 2,3,4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【Next-Key Lock】锁住 (1, 5]（左开右闭）</span></span>
<span class="line"><span>  SELECT * FROM t WHERE id = 5 FOR UPDATE;   &lt; RR 下默认是这个</span></span>
<span class="line"><span>  &gt; 锁住 id=5 这条记录 + (1,5) 这个间隙</span></span></code></pre></div><p><strong>为什么 RR 默认用 Next-Key Lock</strong>：因为只锁记录防不住&quot;插入&quot;（幻读）。加上间隙锁才能阻止别人在空隙里插新行。</p><p><strong>RC 级别下没有间隙锁</strong>，只有记录锁。</p><h3 id="五、加锁规则-实用口诀" tabindex="-1">五、加锁规则（实用口诀） <a class="header-anchor" href="#五、加锁规则-实用口诀" aria-label="Permalink to &quot;五、加锁规则（实用口诀）&quot;">​</a></h3><p>InnoDB 在 RR 下的加锁规则，可以总结成几条（这是《MySQL 实战 45 讲》里的经典总结）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 加锁的基本单位是 Next-Key Lock</span></span>
<span class="line"><span>② 查找过程中访问到的对象才会加锁</span></span>
<span class="line"><span>③ 索引上的等值查询，给唯一索引加锁时，Next-Key Lock 退化为记录锁</span></span>
<span class="line"><span>④ 索引上的等值查询，向右遍历时最后一个不满足条件的值，Next-Key Lock 退化为间隙锁</span></span>
<span class="line"><span>⑤ 唯一索引上的范围查询会访问到不满足条件的第一个值为止</span></span></code></pre></div><p><strong>实战中最该记住的两条</strong>：</p><ul><li><strong>唯一索引等值查询命中 &gt; 只锁一行</strong>（规则 ③），这是最理想的情况。</li><li><strong>非唯一索引等值查询 &gt; 会锁住&quot;值相等的所有行 + 后面的间隙&quot;</strong>，锁范围比想象的大。</li></ul><h3 id="六、死锁-怎么产生-怎么处理" tabindex="-1">六、死锁：怎么产生，怎么处理 <a class="header-anchor" href="#六、死锁-怎么产生-怎么处理" aria-label="Permalink to &quot;六、死锁：怎么产生，怎么处理&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务 A：UPDATE t SET x=1 WHERE id=1;   （持有 id=1 的 X 锁）</span></span>
<span class="line"><span>事务 B：UPDATE t SET x=2 WHERE id=2;   （持有 id=2 的 X 锁）</span></span>
<span class="line"><span>事务 A：UPDATE t SET x=1 WHERE id=2;   （等 B 释放 id=2）</span></span>
<span class="line"><span>事务 B：UPDATE t SET x=2 WHERE id=1;   （等 A 释放 id=1）</span></span>
<span class="line"><span>&gt; 死锁</span></span></code></pre></div><p><strong>四个必要条件</strong>（和 OS 完全一样）：互斥、持有并等待、不可剥夺、循环等待。</p><p><strong>InnoDB 的处理方式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 死锁检测（默认开启 innodb_deadlock_detect = ON）</span></span>
<span class="line"><span>   每次加锁时检查&quot;等待图&quot;有没有环 &gt; 有环就报错，回滚代价最小的事务</span></span>
<span class="line"><span>   代价：O(n²) 的检测开销（n 是等待的事务数），高并发时很吃 CPU</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 死锁超时（innodb_lock_wait_timeout，默认 50 秒）</span></span>
<span class="line"><span>   等太久了自动放弃</span></span>
<span class="line"><span>   代价：响应慢，且可能回滚了不该回滚的事务</span></span></code></pre></div><p><strong>高并发下的死锁检测问题</strong>：1000 个并发事务同时更新同一行，每个都要检测&quot;有没有环&quot;，检测成本 O(n)，总成本 O(n²) &gt; CPU 打满。这就是&quot;热点行更新&quot;的性能瓶颈。</p><p><strong>解法</strong>：</p><ul><li><strong>关闭死锁检测</strong>，靠超时兜底（适合冲突极少的场景）。</li><li><strong>减少热点</strong>：把一行拆成多行（比如账户余额拆成 10 个子账户，随机选一个更新）。</li><li><strong>在应用层串行化</strong>：用队列把对同一行的更新排队。</li></ul><h3 id="七、怎么避免死锁-实战" tabindex="-1">七、怎么避免死锁（实战） <a class="header-anchor" href="#七、怎么避免死锁-实战" aria-label="Permalink to &quot;七、怎么避免死锁（实战）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 按固定顺序访问资源</span></span>
<span class="line"><span>   所有事务都按 id 升序更新 &gt; 不会形成环</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 缩短事务</span></span>
<span class="line"><span>   事务越长，持有锁越久，冲突概率越大</span></span>
<span class="line"><span>   &gt; 把&quot;查询&quot;放到事务外，事务里只做写</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 用索引，避免锁全表</span></span>
<span class="line"><span>   没走索引的 UPDATE 会锁所有行 &gt; 极易死锁</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ 降低隔离级别到 RC</span></span>
<span class="line"><span>   RC 没有间隙锁，锁范围小，死锁概率大幅下降</span></span>
<span class="line"><span></span></span>
<span class="line"><span>⑤ 避免大事务批量更新</span></span>
<span class="line"><span>   拆成小批次（每次 100 行），减少锁持有时间</span></span></code></pre></div><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果只有表锁" tabindex="-1">反事实 1：如果只有表锁 <a class="header-anchor" href="#反事实-1-如果只有表锁" aria-label="Permalink to &quot;反事实 1：如果只有表锁&quot;">​</a></h3><p>并发度极低。一个用户下单锁住整张订单表，其他用户全部排队。这就是 MyISAM 的问题（它只支持表锁）。</p><p><strong>InnoDB 的行锁是它取代 MyISAM 的核心原因</strong>。</p><h3 id="反事实-2-如果没有意向锁" tabindex="-1">反事实 2：如果没有意向锁 <a class="header-anchor" href="#反事实-2-如果没有意向锁" aria-label="Permalink to &quot;反事实 2：如果没有意向锁&quot;">​</a></h3><p>加表锁时要遍历所有行检查行锁，O(n) 的开销。有了意向锁，O(1) 就能判断。</p><h3 id="反事实-3-如果没有间隙锁" tabindex="-1">反事实 3：如果没有间隙锁 <a class="header-anchor" href="#反事实-3-如果没有间隙锁" aria-label="Permalink to &quot;反事实 3：如果没有间隙锁&quot;">​</a></h3><p>RR 级别下，<code>SELECT ... FOR UPDATE</code> 只能锁住已存在的行，别人仍能在范围内插入新行 &gt; 幻读。间隙锁是&quot;锁住未来的行&quot;。</p><p><strong>代价</strong>：锁范围变大，死锁概率上升。这是&quot;正确性换性能&quot;的典型。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：InnoDB 有哪些锁？</strong></p><blockquote><p>按粒度：表锁、意向锁、行锁（记录锁 / 间隙锁 / Next-Key Lock / 插入意向锁）。 按兼容性：共享锁（S）、排他锁（X）。</p></blockquote><p><strong>Q：为什么 InnoDB 的行锁实际上是锁索引？</strong></p><blockquote><p>因为行锁加在索引记录上。没走索引就定位不到记录，只能锁所有行（表现为&quot;锁表&quot;）。所以<strong>索引不仅影响查询速度，还影响锁的范围</strong>。</p></blockquote><p><strong>Q：间隙锁的作用？有什么代价？</strong></p><blockquote><p>作用：阻止在间隙中插入，解决 RR 下的幻读。 代价：锁范围大，并发度下降，死锁概率上升。这也是很多公司改 RC 的原因。</p></blockquote><p><strong>Q：怎么避免死锁？</strong></p><blockquote><p>固定访问顺序、缩短事务、用索引避免锁全表、降级到 RC、批量操作拆小。</p></blockquote><p><strong>Q：死锁检测有什么问题？</strong></p><blockquote><p>每次加锁都要检测等待图，O(n) 复杂度，高并发下总成本 O(n²)，CPU 打满。解法：关掉检测靠超时、拆分热点行、应用层排队。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务怎么保证隔离？（锁 + MVCC）</span></span>
<span class="line"><span>  &gt; 锁有哪些？（S/X、表/行、间隙锁）</span></span>
<span class="line"><span>    &gt; 行锁加在哪？（索引上）</span></span>
<span class="line"><span>      &gt; 没走索引会怎样？（锁全表）</span></span>
<span class="line"><span>        &gt; 间隙锁干什么？（防幻读）</span></span>
<span class="line"><span>          &gt; 代价是什么？（死锁）</span></span>
<span class="line"><span>            &gt; 怎么避免？（固定顺序、缩事务、RC）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：死锁四条件、锁的兼容性，和 OS 完全同源</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/db/03">隔离级别与 MVCC</a>：锁是 MVCC 之外的另一条路，两者配合使用</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：<strong>索引决定了锁的范围</strong>，这是索引的第二个重要作用</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：<code>EXPLAIN</code> 看到 <code>type=ALL</code> 意味着全表扫，也意味着可能锁全表</li><li><strong>&gt; 影响</strong> 工程实践：热点账户、秒杀扣库存、批量更新，都是死锁高发场景</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么&quot;没走索引的 UPDATE&quot;会锁全表？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 InnoDB 的行锁<strong>加在索引记录上</strong>。</p><p>如果 <code>UPDATE t SET x=1 WHERE name=&#39;张三&#39;</code> 而 <code>name</code> 没有索引：</p><ol><li>数据库无法通过索引定位到具体行，只能<strong>全表扫描</strong>。</li><li>扫描过程中，<strong>每一行都会被访问到</strong>，按加锁规则&quot;访问到的对象才会加锁&quot;，于是<strong>每一行都被加了锁</strong>。</li><li>表现为&quot;锁全表&quot;。</li></ol><p>后果：</p><ul><li>其他事务改任何一行都会被阻塞。</li><li>死锁概率大幅上升。</li><li>并发度直接降到 1。</li></ul><p><strong>这就是&quot;给 WHERE 条件加索引&quot;不只是优化查询，更是避免锁表</strong>。</p></details><p><strong>Q2：RC 级别下为什么没有间隙锁？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 <strong>RC 级别允许幻读</strong>，所以不需要间隙锁来防它。</p><p>RC 的设计目标是&quot;读已提交&quot;，只保证&quot;不读到未提交的数据&quot;，不保证&quot;同一事务内两次读结果一致&quot;。所以：</p><ul><li>每次 SELECT 生成新的 ReadView（能读到别人刚提交的）。</li><li>加锁时只锁命中的记录，不锁间隙。</li></ul><p><strong>好处</strong>：锁范围小，并发高，死锁少。 <strong>代价</strong>：幻读存在，业务层要自己处理（比如用 <code>SELECT ... FOR UPDATE</code> 时，仍然可能插入新行）。</p><p>这也是&quot;隔离级别是权衡，不是越高越好&quot;的体现。</p></details><p><strong>Q3：为什么&quot;按固定顺序更新&quot;能避免死锁？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为死锁的第四个条件是<strong>循环等待</strong>：A 等 B 的资源，B 等 A 的资源。</p><p>如果所有事务都按&quot;id 从小到大&quot;的顺序加锁：</p><ul><li>事务 A 要改 id=1 和 id=2 &gt; 先锁 1，再锁 2</li><li>事务 B 也要改 id=1 和 id=2 &gt; 也必须先锁 1</li></ul><p>那么 B 在等 1 的时候，A 已经持有 1 并去申请 2。此时 2 没人占，A 拿到就完成了。B 等 A 释放 1 就行。</p><p><strong>不可能出现&quot;A 持有 2 等 1、B 持有 1 等 2&quot;</strong>——因为没人会先拿 2 再拿 1。</p><p><strong>代价</strong>：可能需要把一批操作排序（业务上不一定自然有序），且跨表操作时&quot;全局顺序&quot;难以定义。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;锁书&quot;类比会让人以为锁是加在&quot;行&quot;上</strong>。实际是加在<strong>索引记录</strong>上，所以没有索引就没有&quot;行锁&quot;，只有全表锁。</li><li><strong>间隙锁不锁记录本身</strong>。它锁的是&quot;两条记录之间的空间&quot;，所以 <code>SELECT ... WHERE id=5 FOR UPDATE</code> 在 RR 下锁的是 <code>(1,5]</code>，包括 1 到 5 之间的空隙。</li><li><strong>意向锁不阻塞行锁</strong>。IS 和 IX 之间是兼容的，它只和表级 S/X 锁冲突。很多人误以为意向锁会互相阻塞。</li><li><strong>死锁不一定是 bug</strong>。高并发下死锁是正常的，数据库会自动回滚一个。<strong>关键是应用层要能处理&quot;死锁异常并重试&quot;</strong>。</li><li><strong><code>SELECT ... FOR UPDATE</code> 在 RC 和 RR 下锁范围不同</strong>。同样的 SQL，换个隔离级别，锁的行数可能差很多。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出 S 锁和 X 锁的兼容矩阵</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能解释&quot;为什么需要意向锁&quot;（要说出&quot;避免遍历所有行&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说清&quot;行锁加在索引上&quot;，并由此推出&quot;没走索引会锁全表&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能区分记录锁、间隙锁、Next-Key Lock 三者的锁范围</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出 RR 和 RC 在加锁上的区别（有无间隙锁）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能说出至少 4 种避免死锁的实战做法</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能解释&quot;死锁检测在高并发下为什么是瓶颈&quot;（O(n²)）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,78)])])}const h=a(o,[["render",e]]);export{g as __pageData,h as default};
